1	import { BadRequestException, ConflictException, ForbiddenException, Injectable, NotFoundException } from '@nestjs/common';
2	import { ConfigService } from '@nestjs/config';
3	import { SupabaseService } from '../supabase/supabase.service';
4	import { PagBankClient } from '../pagamentos/pagbank.client';
5	import { CriarPlanoDto } from './dto/criar-plano.dto';
6	import { AtualizarPlanoDto } from './dto/atualizar-plano.dto';
7	
8	const STATUS_PAGOS = ['PAID', 'COMPLETED', 'AVAILABLE'];
9	
10	const MESES_POR_PERIODICIDADE: Record<string, number> = {
11	  mensal: 1,
12	  trimestral: 3,
13	  anual: 12,
14	};
15	
16	const somarMeses = (data: Date, meses: number) => {
17	  const d = new Date(data);
18	  d.setMonth(d.getMonth() + meses);
19	  return d;
20	};
21	
22	const somarDias = (data: Date, dias: number) => {
23	  const d = new Date(data);
24	  d.setDate(d.getDate() + dias);
25	  return d;
26	};
27	
28	@Injectable()
29	export class PlanosService {
30	  constructor(
31	    private supabase: SupabaseService,
32	    private config: ConfigService,
33	  ) {}
34	
35	  // ── CRUD de planos ──────────────────────────────────────────────
36	
37	  async listarPlanos() {
38	    const { data, error } = await this.supabase.client
39	      .from('planos')
40	      .select('*')
41	      .order('valor', { ascending: true });
42	    if (error) throw error;
43	    return { planos: data ?? [] };
44	  }
45	
46	  async buscarPlano(id: number) {
47	    const { data, error } = await this.supabase.client
48	      .from('planos')
49	      .select('*')
50	      .eq('id', id)
51	      .maybeSingle();
52	    if (error) throw error;
53	    if (!data) throw new NotFoundException('Plano não encontrado');
54	    return data;
55	  }
56	
57	  async criarPlano(body: CriarPlanoDto) {
58	    const { data, error } = await this.supabase.client
59	      .from('planos')
60	      .insert({
61	        nome: body.nome,
62	        valor: body.valor,
63	        periodicidade: body.periodicidade,
64	        limite_produtos: body.limite_produtos ?? null,
65	        piso_faturamento: body.piso_faturamento ?? null,
66	        trial_dias: body.trial_dias ?? 0,
67	        ativo: body.ativo ?? true,
68	        inclui_delivery: body.inclui_delivery ?? true,
69	        inclui_salao: body.inclui_salao ?? false,
70	      })
71	      .select()
72	      .single();
73	    if (error) throw error;
74	    return data;
75	  }
76	
77	  async atualizarPlano(id: number, body: AtualizarPlanoDto) {
78	    const campos: Record<string, any> = { updated_at: new Date().toISOString() };
79	    if (body.nome !== undefined) campos.nome = body.nome;
80	    if (body.valor !== undefined) campos.valor = body.valor;
81	    if (body.periodicidade !== undefined) campos.periodicidade = body.periodicidade;
82	    if (body.limite_produtos !== undefined) campos.limite_produtos = body.limite_produtos;
83	    if (body.piso_faturamento !== undefined) campos.piso_faturamento = body.piso_faturamento;
84	    if (body.trial_dias !== undefined) campos.trial_dias = body.trial_dias;
85	    if (body.ativo !== undefined) campos.ativo = body.ativo;
86	    if (body.inclui_delivery !== undefined) campos.inclui_delivery = body.inclui_delivery;
87	    if (body.inclui_salao !== undefined) campos.inclui_salao = body.inclui_salao;
88	
89	    const { data, error } = await this.supabase.client
90	      .from('planos')
91	      .update(campos)
92	      .eq('id', id)
93	      .select()
94	      .single();
95	    if (error) throw error;
96	    if (!data) throw new NotFoundException('Plano não encontrado');
97	    return data;
98	  }
99	
100	  async removerPlano(id: number) {
101	    const { count, error: countErro } = await this.supabase.client
102	      .from('assinaturas')
103	      .select('id', { count: 'exact', head: true })
104	      .eq('plano_id', id);
105	    if (countErro) throw countErro;
106	    if ((count ?? 0) > 0) {
107	      throw new ConflictException(
108	        'Este plano tem lojas vinculadas — desative com "ativo: false" em vez de remover',
109	      );
110	    }
111	
112	    const { error } = await this.supabase.client.from('planos').delete().eq('id', id);
113	    if (error) throw error;
114	    return { ok: true };
115	  }
