117	  // ── Assinaturas (loja <-> plano) ────────────────────────────────
118	
119	  async listarAssinaturas() {
120	    const { data, error } = await this.supabase.client
121	      .from('assinaturas')
122	      .select('*, restaurants(name), planos(nome, valor, periodicidade)')
123	      .order('created_at', { ascending: false });
124	    if (error) throw error;
125	    return { assinaturas: data ?? [] };
126	  }
