128	  private async buscarAssinaturaRaw(restaurantId: number) {
129	    const { data, error } = await this.supabase.client
130	      .from('assinaturas')
131	      .select('*, planos(*)')
132	      .eq('restaurant_id', restaurantId)
133	      .maybeSingle();
134	    if (error) throw error;
135	    return data;
136	  }
137	
138	  async buscarAssinaturaPorRestaurante(restaurantId: number) {
139	    const assinatura = await this.buscarAssinaturaRaw(restaurantId);
140	    if (!assinatura) throw new NotFoundException('Loja não tem assinatura');
141	
142	    const { data: faturas, error } = await this.supabase.client
143	      .from('plano_faturas')
144	      .select('*')
145	      .eq('restaurant_id', restaurantId)
146	      .order('periodo_inicio', { ascending: false });
147	    if (error) throw error;
148	
149	    return { assinatura, faturas: faturas ?? [] };
150	  }
151	
152	  async atribuirAssinatura(restaurantId: number, planoId: number) {
153	    const plano = await this.buscarPlano(planoId);
154	
155	    const { data: restaurante, error: restErro } = await this.supabase.client
156	      .from('restaurants').select('id').eq('id', restaurantId).maybeSingle();
157	    if (restErro) throw restErro;
158	    if (!restaurante) throw new NotFoundException('Loja não encontrada');
159	
160	    // Módulos liberados na loja passam a refletir o que o plano inclui
161	    const { error: moduloErro } = await this.supabase.client
162	      .from('restaurants')
163	      .update({
164	        modulo_delivery: plano.inclui_delivery,
165	        modulo_salao: plano.inclui_salao,
166	        updated_at: new Date().toISOString(),
167	      })
168	      .eq('id', restaurantId);
169	    if (moduloErro) throw moduloErro;
170	
171	    const existente = await this.buscarAssinaturaRaw(restaurantId);
172	    const agora = new Date();
173	    const temTrial = (plano.trial_dias ?? 0) > 0;
174	    const trialFim = temTrial ? somarDias(agora, plano.trial_dias) : null;
175	
176	    if (existente) {
177	      // Troca de plano reinicia o ciclo de cobrança: recalcula trial/status a
178	      // partir do plano novo (senão um plano com trial_dias=0 continuaria preso
179	      // no status "trial" herdado do plano anterior).
180	      const { data, error } = await this.supabase.client
181	        .from('assinaturas')
182	        .update({
183	          plano_id: planoId,
184	          status: temTrial ? 'trial' : 'ativa',
185	          trial_fim: trialFim?.toISOString() ?? null,
186	          ultimo_periodo_faturado_fim: (trialFim ?? agora).toISOString(),
187	          updated_at: agora.toISOString(),
188	        })
189	        .eq('id', existente.id)
190	        .select()
191	        .single();
192	      if (error) throw error;
193	      return data;
194	    }
195	
196	    const { data, error } = await this.supabase.client
197	      .from('assinaturas')
198	      .insert({
199	        restaurant_id: restaurantId,
200	        plano_id: planoId,
201	        status: temTrial ? 'trial' : 'ativa',
202	        data_inicio: agora.toISOString(),
203	        trial_fim: trialFim?.toISOString() ?? null,
204	        ultimo_periodo_faturado_fim: (trialFim ?? agora).toISOString(),
205	      })
206	      .select()
207	      .single();
208	    if (error) throw error;
209	    return data;
210	  }
211	
212	  async cancelarAssinatura(restaurantId: number) {
213	    const existente = await this.buscarAssinaturaRaw(restaurantId);
214	    if (!existente) throw new NotFoundException('Loja não tem assinatura');
215	
216	    const { data, error } = await this.supabase.client
217	      .from('assinaturas')
218	      .update({ status: 'cancelada', data_cancelamento: new Date().toISOString(), updated_at: new Date().toISOString() })
219	      .eq('id', existente.id)
220	      .select()
221	      .single();
222	    if (error) throw error;
223	    return data;
224	  }
