226	  // ── Limite de produtos ──────────────────────────────────────────
227	
228	  async verificarLimiteProdutos(restaurantId: number) {
229	    const assinatura = await this.buscarAssinaturaRaw(restaurantId);
230	    if (!assinatura || assinatura.status === 'cancelada') return; // loja sem plano = sem limite
231	    const limite = assinatura.planos?.limite_produtos;
232	    if (limite == null) return; // ilimitado
233	
234	    const { count, error } = await this.supabase.client
235	      .from('products')
236	      .select('id', { count: 'exact', head: true })
237	      .eq('restaurant_id', restaurantId)
238	      .eq('is_active', true);
239	    if (error) throw error;
240	
241	    if ((count ?? 0) >= limite) {
242	      throw new ForbiddenException(
243	        `Limite de ${limite} produtos do plano "${assinatura.planos.nome}" atingido. Faça upgrade de plano para cadastrar mais produtos.`,
244	      );
245	    }
246	  }
