248	  // ── Faturamento / geração lazy de fatura ────────────────────────
249	
250	  private async diasTolerancia() {
251	    const { data } = await this.supabase.client
252	      .from('platform_settings').select('config').eq('id', 1).maybeSingle();
253	    const cfg = (data?.config ?? {}) as Record<string, any>;
254	    return cfg.plano_dias_tolerancia ?? 3;
255	  }
256	
257	  // Marca pendente->vencida, gera faturas de todo período fechado ainda não
258	  // faturado, e devolve o status atual de bloqueio da loja.
259	  // forcar=true também gera fatura do período atual mesmo que ainda não tenha
260	  // fechado (usado pelo botão "Renovar agora"/"Gerar fatura" sob demanda).
261	  async sincronizarPeriodo(restaurantId: number, forcar = false) {
262	    const assinatura = await this.buscarAssinaturaRaw(restaurantId);
263	    if (!assinatura || assinatura.status === 'cancelada') {
264	      return { bloqueado: false, dias_atraso: 0, fatura_pendente_id: null, plano_nome: null, proxima_cobranca: null };
265	    }
266	
267	    const agora = new Date();
268	    const plano = assinatura.planos;
269	    const meses = MESES_POR_PERIODICIDADE[plano.periodicidade] ?? 1;
270	
271	    // Marca vencidas
272	    await this.supabase.client
273	      .from('plano_faturas')
274	      .update({ status: 'vencida', atualizado_em: agora.toISOString() })
275	      .eq('assinatura_id', assinatura.id)
276	      .eq('status', 'pendente')
277	      .lt('vencimento', agora.toISOString());
278	
279	    // Gera períodos fechados pendentes de fatura (+ o período atual se forcar=true)
280	    let inicioPeriodo = assinatura.ultimo_periodo_faturado_fim
281	      ? new Date(assinatura.ultimo_periodo_faturado_fim)
282	      : new Date(assinatura.data_inicio);
283	    let ultimoFimFaturado = assinatura.ultimo_periodo_faturado_fim
284	      ? new Date(assinatura.ultimo_periodo_faturado_fim)
285	      : null;
286	
287	    // eslint-disable-next-line no-constant-condition
288	    while (true) {
289	      const fimPeriodo = somarMeses(inicioPeriodo, meses);
290	      const periodoFechado = fimPeriodo < agora;
291	      if (!periodoFechado && !forcar) break;
292	
293	      if (!periodoFechado) {
294	        // Período em aberto forçado: se já existe fatura pra esse período (de um
295	        // "Renovar agora" anterior), não gera outra nem avança o ciclo de novo —
296	        // senão cada clique empurraria a cobrança um mês pra frente.
297	        const { data: jaExiste, error: existeErro } = await this.supabase.client
298	          .from('plano_faturas')
299	          .select('id')
300	          .eq('assinatura_id', assinatura.id)
301	          .eq('periodo_inicio', inicioPeriodo.toISOString())
302	          .maybeSingle();
303	        if (existeErro) throw existeErro;
304	        if (jaExiste) break;
305	      }
306	
307	      const { data: faturamentoRows, error: fatErro } = await this.supabase.client
308	        .from('orders')
309	        .select('total')
310	        .eq('restaurant_id', restaurantId)
311	        .eq('status', 'delivered')
312	        .gte('created_at', inicioPeriodo.toISOString())
313	        .lt('created_at', fimPeriodo.toISOString());
314	      if (fatErro) throw fatErro;
315	
316	      const faturamento = (faturamentoRows ?? []).reduce((acc, o: any) => acc + (o.total ?? 0), 0);
317	
318	      const isento = plano.piso_faturamento != null && faturamento < plano.piso_faturamento;
319	      const valorFatura = isento ? 0 : plano.valor;
320	      const vencimento = somarDias(fimPeriodo, 5);
321	
322	      const { error: insErro } = await this.supabase.client
323	        .from('plano_faturas')
324	        .insert({
325	          assinatura_id: assinatura.id,
326	          restaurant_id: restaurantId,
327	          periodo_inicio: inicioPeriodo.toISOString(),
328	          periodo_fim: fimPeriodo.toISOString(),
329	          valor: valorFatura,
330	          status: isento ? 'isenta' : 'pendente',
331	          vencimento: vencimento.toISOString(),
332	        });
333	      // Ignora conflito de unicidade (fatura já gerada em corrida concorrente)
334	      if (insErro && !String(insErro.message).includes('duplicate')) throw insErro;
335	
336	      ultimoFimFaturado = fimPeriodo;
337	      inicioPeriodo = fimPeriodo;
338	
339	      if (!periodoFechado) break; // gerou o período em aberto sob demanda — não continua pro futuro
340	    }
341	
342	    if (ultimoFimFaturado && ultimoFimFaturado.getTime() !== new Date(assinatura.ultimo_periodo_faturado_fim ?? 0).getTime()) {
343	      await this.supabase.client
344	        .from('assinaturas')
345	        .update({ ultimo_periodo_faturado_fim: ultimoFimFaturado.toISOString(), updated_at: agora.toISOString() })
346	        .eq('id', assinatura.id);
347	    }
348	
349	    // Recalcula bloqueio com base no estado atual das faturas
350	    const tolerancia = await this.diasTolerancia();
351	    const { data: pendentes, error: pendErro } = await this.supabase.client
352	      .from('plano_faturas')
353	      .select('id, vencimento, status')
354	      .eq('assinatura_id', assinatura.id)
355	      .in('status', ['pendente', 'vencida'])
356	      .order('vencimento', { ascending: true });
357	    if (pendErro) throw pendErro;
358	
359	    let bloqueado = false;
360	    let diasAtraso = 0;
361	    let faturaPendenteId: number | null = null;
362	    if ((pendentes ?? []).length > 0) {
363	      faturaPendenteId = pendentes[0].id;
364	      const vencimento = new Date(pendentes[0].vencimento);
365	      diasAtraso = Math.max(0, Math.floor((agora.getTime() - vencimento.getTime()) / 86400000));
366	      bloqueado = diasAtraso > tolerancia;
367	    }
368	
369	    const proximaCobranca = somarMeses(ultimoFimFaturado ?? inicioPeriodo, meses);
370	
371	    return {
372	      bloqueado,
373	      dias_atraso: diasAtraso,
374	      fatura_pendente_id: faturaPendenteId,
375	      plano_nome: plano.nome,
376	      proxima_cobranca: proximaCobranca.toISOString(),
377	    };
378	  }
