380	  async detalhePlanoRestaurante(restaurantId: number) {
381	    const status = await this.sincronizarPeriodo(restaurantId);
382	    const { assinatura, faturas } = await this.buscarAssinaturaPorRestaurante(restaurantId);
383	
384	    const { count: produtosAtivos, error } = await this.supabase.client
385	      .from('products')
386	      .select('id', { count: 'exact', head: true })
387	      .eq('restaurant_id', restaurantId)
388	      .eq('is_active', true);
389	    if (error) throw error;
390	
391	    return {
392	      ...status,
393	      assinatura,
394	      faturas,
395	      produtos_ativos: produtosAtivos ?? 0,
396	      limite_produtos: assinatura.planos?.limite_produtos ?? null,
397	    };
398	  }
399	
400	  async gerarFaturaManual(restaurantId: number) {
401	    await this.sincronizarPeriodo(restaurantId, true);
402	    return this.buscarAssinaturaPorRestaurante(restaurantId);
403	  }
404	
405	  // Dono renovando/antecipando a cobrança da própria loja pelo painel do plano
406	  async renovarAgora(restaurantId: number) {
407	    return this.sincronizarPeriodo(restaurantId, true);
408	  }
