410	  // ── Faturas (visão admin) ───────────────────────────────────────
411	
412	  async listarFaturas(filtros: { restaurant_id?: number; status?: string }) {
413	    let q = this.supabase.client
414	      .from('plano_faturas')
415	      .select('*, restaurants(name)')
416	      .order('vencimento', { ascending: false });
417	    if (filtros.restaurant_id) q = q.eq('restaurant_id', filtros.restaurant_id);
418	    if (filtros.status) q = q.eq('status', filtros.status);
419	    const { data, error } = await q;
420	    if (error) throw error;
421	    return { faturas: data ?? [] };
422	  }
423	
424	  async buscarFatura(id: number) {
425	    const { data, error } = await this.supabase.client
426	      .from('plano_faturas').select('*').eq('id', id).maybeSingle();
427	    if (error) throw error;
428	    if (!data) throw new NotFoundException('Fatura não encontrada');
429	    return data;
430	  }
