432	  async buscarFaturaDoRestaurante(restaurantId: number, id: number) {
433	    const fatura = await this.buscarFatura(id);
434	    if (fatura.restaurant_id !== restaurantId) throw new NotFoundException('Fatura não encontrada');
435	    return fatura;
