438	  async marcarFaturaPaga(id: number) {
439	    const { data, error } = await this.supabase.client
440	      .from('plano_faturas')
441	      .update({ status: 'paga', pago_em: new Date().toISOString(), atualizado_em: new Date().toISOString() })
442	      .eq('id', id)
443	      .select()
444	      .single();
445	    if (error) throw error;
446	    if (!data) throw new NotFoundException('Fatura não encontrada');
447	    return data;
