450	  // ── Pagamento via PagBank (cobrança direta loja -> plataforma, sem split) ──
451	
452	  async pagarFatura(restaurantId: number, faturaId: number, customer: { nome: string; email: string; cpf_cnpj: string }) {
453	    const fatura = await this.buscarFaturaDoRestaurante(restaurantId, faturaId);
454	    if (fatura.status === 'paga') throw new BadRequestException('Fatura já está paga');
455	    if (fatura.status === 'isenta' || fatura.status === 'cancelada') {
456	      throw new BadRequestException('Esta fatura não pode ser paga');
457	    }
458	
459	    // Reaproveita o QR já gerado pra essa fatura em vez de abrir ordem nova a cada clique
460	    if (fatura.pix_code && fatura.pagbank_order_id) {
461	      return { pix_code: fatura.pix_code, pix_qr_url: fatura.pix_qr_url, fatura_id: fatura.id };
462	    }
463	
464	    const { data: platData } = await this.supabase.client
465	      .from('platform_settings').select('config').eq('id', 1).maybeSingle();
466	    const platCfg = (platData?.config ?? {}) as Record<string, any>;
467	
468	    const token = platCfg.pagbank_platform_token || this.config.get<string>('PAGBANK_PLATFORM_TOKEN') || '';
469	    if (!token) throw new BadRequestException('PagBank da plataforma não configurado — fale com o suporte');
470	    const sandbox = platCfg.pagbank_sandbox ?? (this.config.get('PAGBANK_SANDBOX') !== 'false');
471	
472	    const baseWebhook =
473	      platCfg.pagbank_webhook_url ||
474	      this.config.get<string>('PAGBANK_WEBHOOK_URL') ||
475	      'http://localhost:3002/pagamentos/webhook';
476	    const webhookUrl = baseWebhook.replace('/pagamentos/webhook', '/planos/webhook');
477	
478	    const valorCentavos = Math.round(fatura.valor * 100);
479	    const refId = `PLANO_${fatura.id}_${Date.now()}`;
480	    const client = new PagBankClient(token, sandbox);
481	
482	    let resposta: any;
483	    try {
484	      resposta = await client.criarOrdemPix({
485	        reference_id: refId,
486	        valor_centavos: valorCentavos,
487	        customer: {
488	          name: customer.nome,
489	          email: customer.email,
490	          tax_id: customer.cpf_cnpj.replace(/\D/g, ''),
491	        },
492	        itens: [{ name: `Assinatura — fatura #${fatura.id}`, quantity: 1, unit_amount: valorCentavos }],
493	        webhook_url: webhookUrl,
494	      });
495	    } catch (e: any) {
496	      throw new BadRequestException(e?.message ?? 'Falha ao gerar cobrança no PagBank');
497	    }
498	
499	    const qrCode = resposta?.qr_codes?.[0];
500	    const pixCode = qrCode?.text ?? null;
501	    const pixQrUrl = qrCode?.links?.find((l: any) => l.media === 'image/png')?.href ?? null;
502	
503	    const { error } = await this.supabase.client
504	      .from('plano_faturas')
505	      .update({
506	        pagbank_order_id: resposta.id,
507	        reference_id: refId,
508	        pix_code: pixCode,
509	        pix_qr_url: pixQrUrl,
510	        atualizado_em: new Date().toISOString(),
511	      })
512	      .eq('id', fatura.id);
513	    if (error) throw error;
514	
515	    return { pix_code: pixCode, pix_qr_url: pixQrUrl, fatura_id: fatura.id };
516	  }
