1	import React, { useState, useEffect } from 'react';
2	import { useNavigate } from 'react-router-dom';
3	import { getPlataformaConfig, updatePlataformaConfig, getRedeInfo, getEmpresas } from '../../services/adminService';
4	import { useAuth } from '../../contexts/AuthContext';
5	import Icon from '../../components/AppIcon';
6	import { ThemeToggle } from '../../contexts/ThemeContext';
7	
8	const AdminConfiguracoes = () => {
9	  const navigate = useNavigate();
10	  const { signOut } = useAuth();
11	  const [config, setConfig] = useState(null);
12	  const [loading, setLoading] = useState(true);
13	  const [salvando, setSalvando] = useState(false);
14	  const [sucesso, setSucesso] = useState(false);
15	  const [erro, setErro] = useState(null);
16	
17	  const [form, setForm] = useState({
18	    pagbank_platform_token: '',
19	    pagbank_platform_account_id: '',
20	    pagbank_sandbox: true,
21	    cloudflare_tunnel_token: '',
22	    cloudflare_domain: '',
23	  });
24	  const [salvandoCf, setSalvandoCf] = useState(false);
25	  const [sucessoCf, setSucessoCf] = useState(false);
26	  const [erroCf, setErroCf] = useState(null);
27	  const [redeInfo, setRedeInfo] = useState(null);
28	
29	  const [modoIndividual, setModoIndividual] = useState(false);
30	  const [modoIndividualRestauranteId, setModoIndividualRestauranteId] = useState('');
31	  const [empresas, setEmpresas] = useState([]);
32	  const [salvandoModo, setSalvandoModo] = useState(false);
33	  const [sucessoModo, setSucessoModo] = useState(false);
34	  const [erroModo, setErroModo] = useState(null);
35	
36	  const [comissaoPadrao, setComissaoPadrao] = useState('5');
37	  const [diasTolerancia, setDiasTolerancia] = useState('3');
38	  const [salvandoComissao, setSalvandoComissao] = useState(false);
39	  const [sucessoComissao, setSucessoComissao] = useState(false);
40	  const [erroComissao, setErroComissao] = useState(null);
41	
42	  useEffect(() => {
43	    getPlataformaConfig()
44	      .then((d) => {
45	        setConfig(d);
46	        setForm((f) => ({
47	          ...f,
48	          pagbank_platform_account_id: d.pagbank_platform_account_id ?? '',
49	          pagbank_sandbox: d.pagbank_sandbox ?? true,
50	          cloudflare_domain: d.cloudflare_domain ?? '',
51	        }));
52	        setModoIndividual(d.modo_individual ?? false);
53	        setModoIndividualRestauranteId(d.modo_individual_restaurant_id ?? '');
54	        setComissaoPadrao(String(d.comissao_padrao_pct ?? 5));
55	        setDiasTolerancia(String(d.plano_dias_tolerancia ?? 3));
56	      })
57	      .catch((e) => setErro(e.message))
58	      .finally(() => setLoading(false));
59	    getRedeInfo().then(setRedeInfo).catch(() => {});
60	    getEmpresas().then((d) => setEmpresas(d.empresas ?? [])).catch(() => {});
61	  }, []);
62	
63	  const handleSalvarModoIndividual = async (e) => {
64	    e.preventDefault();
65	    setSalvandoModo(true);
66	    setErroModo(null);
67	    setSucessoModo(false);
68	    try {
69	      const payload = {
70	        modo_individual: modoIndividual,
71	        modo_individual_restaurant_id: modoIndividual && modoIndividualRestauranteId
72	          ? parseInt(modoIndividualRestauranteId, 10)
73	          : null,
74	      };
75	      const updated = await updatePlataformaConfig(payload);
76	      setConfig(updated);
77	      setSucessoModo(true);
78	      setTimeout(() => setSucessoModo(false), 3000);
79	    } catch (err) {
80	      setErroModo(err.message);
81	    } finally {
82	      setSalvandoModo(false);
83	    }
84	  };
85	
86	  const handleSalvarComissao = async (e) => {
87	    e.preventDefault();
88	    setSalvandoComissao(true);
89	    setErroComissao(null);
90	    setSucessoComissao(false);
91	    try {
92	      const payload = {
93	        comissao_padrao_pct: parseFloat(comissaoPadrao),
94	        plano_dias_tolerancia: parseInt(diasTolerancia, 10),
95	      };
96	      const updated = await updatePlataformaConfig(payload);
97	      setConfig(updated);
98	      setSucessoComissao(true);
99	      setTimeout(() => setSucessoComissao(false), 3000);
100	    } catch (err) {
101	      setErroComissao(err.message);
102	    } finally {
103	      setSalvandoComissao(false);
104	    }
105	  };
106	
107	  const handleSalvar = async (e) => {
108	    e.preventDefault();
109	    setSalvando(true);
110	    setErro(null);
111	    setSucesso(false);
112	    try {
113	      const payload = {
114	        pagbank_platform_account_id: form.pagbank_platform_account_id.trim(),
115	        pagbank_sandbox: form.pagbank_sandbox,
116	      };
117	      if (form.pagbank_platform_token.trim()) {
118	        payload.pagbank_platform_token = form.pagbank_platform_token.trim();
119	      }
120	      const updated = await updatePlataformaConfig(payload);
121	      setConfig(updated);
122	      setForm((f) => ({ ...f, pagbank_platform_token: '' }));
123	      setSucesso(true);
124	      setTimeout(() => setSucesso(false), 3000);
125	    } catch (err) {
126	      setErro(err.message);
127	    } finally {
128	      setSalvando(false);
129	    }
130	  };
131	
132	  const handleSalvarCloudflare = async (e) => {
133	    e.preventDefault();
134	    setSalvandoCf(true);
135	    setErroCf(null);
136	    setSucessoCf(false);
137	    try {
138	      const payload = { cloudflare_domain: form.cloudflare_domain.trim() };
139	      if (form.cloudflare_tunnel_token.trim()) {
140	        payload.cloudflare_tunnel_token = form.cloudflare_tunnel_token.trim();
141	      }
142	      const updated = await updatePlataformaConfig(payload);
143	      setConfig(updated);
144	      setForm((f) => ({ ...f, cloudflare_tunnel_token: '' }));
145	      setSucessoCf(true);
146	      setTimeout(() => setSucessoCf(false), 3000);
147	    } catch (err) {
148	      setErroCf(err.message);
149	    } finally {
150	      setSalvandoCf(false);
151	    }
152	  };
153	
154	  const NavAdmin = () => (
155	    <nav className="flex gap-2 flex-wrap justify-end">
156	      {[
157	        { label: 'Dashboard', path: '/admin' },
158	        { label: 'Empresas', path: '/admin/empresas' },
159	        { label: 'Categorias', path: '/admin/categorias' },
160	        { label: 'Tipos',      path: '/admin/tipos-estabelecimento' },
161	        { label: 'Tags',       path: '/admin/tags' },
162	        { label: 'Comissões', path: '/admin/comissoes' },
163	        { label: 'Planos', path: '/admin/planos' },
164	        { label: 'Configurações', path: '/admin/configuracoes' },
165	      ].map((l) => (
166	        <button key={l.path} onClick={() => navigate(l.path)}
167	          className={`px-3 py-2 text-sm font-medium rounded-lg ${
168	            l.path === '/admin/configuracoes'
169	              ? 'text-white bg-orange-500'
170	              : 'text-gray-700 dark:text-zinc-300 hover:bg-gray-100 dark:hover:bg-zinc-800'
171	          }`}>
172	          {l.label}
173	        </button>
174	      ))}
175	      <ThemeToggle inline />
176	      <button
177	        onClick={async () => { await signOut(); navigate('/customer-registration-login'); }}
178	        className="px-3 py-2 text-sm font-medium text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-950/40 rounded-lg border border-red-200 dark:border-red-900"
179	      >
180	        Sair
181	      </button>
182	    </nav>
183	  );
184	
185	  return (
186	    <div className="min-h-screen bg-gray-50 dark:bg-zinc-900">
187	      <header className="bg-white dark:bg-zinc-800 border-b dark:border-zinc-700 px-6 py-4 flex items-center justify-between">
188	        <div>
189	          <h1 className="text-xl font-bold text-gray-900 dark:text-zinc-100">Configurações da Plataforma</h1>
190	          <p className="text-sm text-gray-500 dark:text-zinc-400">Integração PagBank Marketplace (Split Payment)</p>
191	        </div>
192	        <NavAdmin />
193	      </header>
194	
195	      <main className="p-6 max-w-2xl mx-auto">
196	        {loading ? (
197	          <div className="flex justify-center py-12">
198	            <div className="w-8 h-8 border-4 border-orange-500 border-t-transparent rounded-full animate-spin" />
199	          </div>
200	        ) : (
201	          <div className="space-y-6">
202	
203	            {/* Status */}
204	            <div className={`rounded-xl border p-4 flex items-start gap-3 ${
205	              config?.configurado ? 'bg-green-50 dark:bg-green-950/30 border-green-200 dark:border-green-900' : 'bg-yellow-50 dark:bg-yellow-950/30 border-yellow-200 dark:border-yellow-900'
206	            }`}>
207	              <Icon
208	                name={config?.configurado ? 'CheckCircle' : 'AlertCircle'}
209	                size={20}
210	                className={`mt-0.5 flex-shrink-0 ${config?.configurado ? 'text-green-600 dark:text-green-400' : 'text-yellow-600 dark:text-yellow-400'}`}
211	              />
212	              <div>
213	                <p className={`text-sm font-semibold ${config?.configurado ? 'text-green-800 dark:text-green-300' : 'text-yellow-800 dark:text-yellow-300'}`}>
214	                  {config?.configurado ? 'Split Payment configurado e ativo' : 'Split Payment não configurado'}
215	                </p>
216	                {config?.configurado ? (
217	                  <p className="text-xs text-green-600 dark:text-green-400 mt-0.5">
218	                    Token: {config.pagbank_platform_token_masked} · Account: {config.pagbank_platform_account_id} · {config.pagbank_sandbox ? 'Sandbox' : 'Produção'}
219	                  </p>
220	                ) : (
221	                  <p className="text-xs text-yellow-700 dark:text-yellow-400 mt-0.5">
222	                    Configure o token e account ID abaixo para ativar o repasse automático aos restaurantes.
223	                  </p>
224	                )}
225	              </div>
226	            </div>
227	
228	            {/* Explicação do fluxo */}
229	            <div className="bg-blue-50 dark:bg-blue-950/30 border border-blue-100 dark:border-blue-900 rounded-xl p-5">
230	              <h2 className="text-sm font-bold text-blue-800 dark:text-blue-300 mb-3 flex items-center gap-2">
231	                <Icon name="Info" size={16} /> Como funciona o Split Payment
232	              </h2>
233	              <ol className="text-xs text-blue-700 dark:text-blue-400 space-y-2 list-decimal list-inside">
234	                <li>Cliente paga → dinheiro vai para a <strong>conta da plataforma</strong> (seu token abaixo)</li>
235	                <li>PagBank divide automaticamente: restaurante recebe a parte dele, você recebe a comissão</li>
236	                <li>Nenhum dinheiro transita manualmente — tudo automático no momento do pagamento</li>
237	              </ol>
238	              <div className="mt-3 text-xs text-blue-600 dark:text-blue-400 bg-blue-100 dark:bg-blue-900/40 rounded-lg p-2">
239	                <strong>Restaurante precisa:</strong> informar o ID da conta deles em /restaurante/config → "ID da conta PagBank"
240	              </div>
241	            </div>
242	
243	            {/* Formulário */}
244	            <div className="bg-white dark:bg-zinc-800 rounded-xl border dark:border-zinc-700 p-6">
245	              <h2 className="font-semibold text-gray-900 dark:text-zinc-100 mb-1">Conta PagBank Marketplace</h2>
246	              <p className="text-sm text-gray-500 dark:text-zinc-400 mb-5">
247	                Obtenha o token e account ID na sua conta PagBank tipo Marketplace/Facilitador.
248	              </p>
249	
250	              <form onSubmit={handleSalvar} className="space-y-4">
251	                {/* Token da plataforma */}
252	                <div>
253	                  <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">
254	                    Token da Plataforma (Marketplace)
255	                    {config?.configurado && (
256	                      <span className="text-xs text-gray-400 dark:text-zinc-500 ml-2">(deixe vazio para manter atual)</span>
257	                    )}
258	                  </label>
259	                  <input
260	                    type="password"
261	                    value={form.pagbank_platform_token}
262	                    onChange={(e) => setForm((f) => ({ ...f, pagbank_platform_token: e.target.value }))}
263	                    placeholder={
264	                      config?.configurado
265	                        ? config.pagbank_platform_token_masked
266	                        : 'Token da conta Marketplace PagBank'
267	                    }
268	                    className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm font-mono bg-white dark:bg-zinc-800 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-orange-400"
269	                  />
270	                  <p className="text-xs text-gray-400 dark:text-zinc-500 mt-1">
271	                    Usado para processar TODOS os pagamentos dos restaurantes da plataforma
272	                  </p>
273	                </div>
274	
275	                {/* Account ID da plataforma */}
276	                <div>
277	                  <label className="block text-sm font-medium text-gray-700 dark:text-zinc-300 mb-1">
278	                    Account ID da Plataforma
279	                  </label>
280	                  <input
281	                    type="text"
282	                    value={form.pagbank_platform_account_id}
283	                    onChange={(e) => setForm((f) => ({ ...f, pagbank_platform_account_id: e.target.value }))}
284	                    placeholder="Ex: ACCT_XXXXXXXXXXXX"
285	                    className="w-full border border-gray-300 dark:border-zinc-700 rounded-lg px-3 py-2 text-sm font-mono bg-white dark:bg-zinc-800 text-gray-900 dark:text-zinc-100 focus:outline-none focus:ring-2 focus:ring-orange-400"
286	                  />
287	                  <p className="text-xs text-gray-400 dark:text-zinc-500 mt-1">
288	                    Conta onde a comissão de cada venda será depositada automaticamente
289	                  </p>
290	                </div>
291	
292	                {/* Sandbox toggle */}
293	                <div className="flex items-center gap-3">
294	                  <button
295	                    type="button"
296	                    onClick={() => setForm((f) => ({ ...f, pagbank_sandbox: !f.pagbank_sandbox }))}
297	                    className={`relative w-10 h-6 rounded-full transition-colors ${
298	                      form.pagbank_sandbox ? 'bg-orange-400' : 'bg-green-500'
299	                    }`}
300	                  >
301	                    <span className={`absolute top-1 w-4 h-4 bg-white rounded-full shadow transition-transform ${
302	                      form.pagbank_sandbox ? 'left-1' : 'left-5'
303	                    }`} />
304	                  </button>
305	                  <div>
306	                    <p className="text-sm font-medium text-gray-700 dark:text-zinc-300">
307	                      {form.pagbank_sandbox ? 'Sandbox (testes)' : 'Produção (cobranças reais)'}
308	                    </p>
309	                    <p className="text-xs text-gray-400 dark:text-zinc-500">
310	                      {form.pagbank_sandbox
311	                        ? 'Pagamentos não são reais — para testes'
312	                        : 'Atenção: pagamentos reais serão processados'}
313	                    </p>
314	                  </div>
315	                </div>
316	
317	                {/* Comissão info */}
318	                <div className="bg-gray-50 dark:bg-zinc-900 border dark:border-zinc-700 rounded-xl p-4">
319	                  <p className="text-xs font-semibold text-gray-700 dark:text-zinc-300 mb-1">Comissão por restaurante</p>
320	                  <p className="text-xs text-gray-500 dark:text-zinc-400">
321	                    Cada restaurante tem sua própria taxa configurada em <strong>Empresas → editar</strong>.
322	                    O campo <code className="bg-gray-100 dark:bg-zinc-800 px-1 rounded">comissao_pct</code> define o % descontado automaticamente no split.
323	                  </p>
324	                </div>
325	
326	                {erro && (
327	                  <div className="p-3 bg-red-50 dark:bg-red-950/30 border border-red-200 dark:border-red-900 rounded-lg text-sm text-red-600 dark:text-red-400">{erro}</div>
328	                )}
329	                {sucesso && (
330	                  <div className="p-3 bg-green-50 dark:bg-green-950/30 border border-green-200 dark:border-green-900 rounded-lg text-sm text-green-700 dark:text-green-400">
331	                    Configuração salva!
332	                  </div>
333	                )}
334	
335	                <button
336	                  type="submit"
337	                  disabled={salvando}
338	                  className="w-full py-2.5 bg-orange-500 text-white rounded-lg font-medium text-sm hover:bg-orange-600 disabled:opacity-50"
339	                >
340	                  {salvando ? 'Salvando...' : 'Salvar configurações'}
341	                </button>
342	              </form>
343	            </div>
344	            {/* ── Modo de instalação ──────────────────────────────── */}
