163	  async atribuirAssinatura(restaurantId: number, planoId: number) {
164	    const plano = await this.buscarPlano(planoId);
165	
166	    const { data: restaurante, error: restErro } = await this.supabase.client
167	      .from('restaurants').select('id').eq('id', restaurantId).maybeSingle();
168	    if (restErro) throw restErro;
169	    if (!restaurante) throw new NotFoundException('Loja não encontrada');
170	
171	    // Módulos liberados na loja passam a refletir o que o plano inclui
172	    const { error: moduloErro } = await this.supabase.client
173	      .from('restaurants')
174	      .update({
175	        modulo_delivery: plano.inclui_delivery,
176	        modulo_salao: plano.inclui_salao,
177	        updated_at: new Date().toISOString(),
178	      })
179	      .eq('id', restaurantId);
180	    if (moduloErro) throw moduloErro;
181	
182	    const existente = await this.buscarAssinaturaRaw(restaurantId);
183	    const agora = new Date();
184	    const temTrial = (plano.trial_dias ?? 0) > 0;
185	    const trialFim = temTrial ? somarDias(agora, plano.trial_dias) : null;
186	
187	    if (existente) {
188	      // Troca de plano reinicia o ciclo de cobrança: recalcula trial/status a
189	      // partir do plano novo (senão um plano com trial_dias=0 continuaria preso
190	      // no status "trial" herdado do plano anterior).
191	      const { data, error } = await this.supabase.client
192	        .from('assinaturas')
193	        .update({
194	          plano_id: planoId,
195	          status: temTrial ? 'trial' : 'ativa',
196	          trial_fim: trialFim?.toISOString() ?? null,
197	          ultimo_periodo_faturado_fim: (trialFim ?? agora).toISOString(),
198	          updated_at: agora.toISOString(),
199	        })
200	        .eq('id', existente.id)
201	        .select()
202	        .single();
203	      if (error) throw error;
204	      return data;
205	    }
206	
207	    const { data, error } = await this.supabase.client
208	      .from('assinaturas')
209	      .insert({
210	        restaurant_id: restaurantId,
211	        plano_id: planoId,
212	        status: temTrial ? 'trial' : 'ativa',
213	        data_inicio: agora.toISOString(),
214	        trial_fim: trialFim?.toISOString() ?? null,
215	        ultimo_periodo_faturado_fim: (trialFim ?? agora).toISOString(),
216	      })
217	      .select()
218	      .single();
219	    if (error) throw error;
220	    return data;
221	  }
