501	    try {
502	      const resposta = await client.buscarChavePublica();
503	      return { public_key: resposta.public_key };
504	    } catch (e: any) {
505	      throw new BadRequestException(e?.message ?? 'Falha ao obter chave pública do PagBank');
506	    }
507	  }
