509	  async pagarFatura(
510	    restaurantId: number,
511	    faturaId: number,
512	    body: { nome: string; email: string; cpf_cnpj: string; metodo?: 'pix' | 'credit_card' | 'debit_card'; card_encrypted?: string; parcelas?: number },
513	  ) {
514	    const fatura = await this.buscarFaturaDoRestaurante(restaurantId, faturaId);
515	    if (fatura.status === 'paga') throw new BadRequestException('Fatura já está paga');
516	    if (fatura.status === 'isenta' || fatura.status === 'cancelada') {
517	      throw new BadRequestException('Esta fatura não pode ser paga');
518	    }
519	
520	    const metodo = body.metodo ?? 'pix';
521	    if (metodo === 'credit_card' || metodo === 'debit_card') {
522	      return this.pagarFaturaCartao(fatura, body, metodo);
523	    }
524	
525	    // Reaproveita o QR já gerado pra essa fatura em vez de abrir ordem nova a cada clique
526	    if (fatura.pix_code && fatura.pagbank_order_id) {
527	      return { pix_code: fatura.pix_code, pix_qr_url: fatura.pix_qr_url, fatura_id: fatura.id };
528	    }
529	
530	    const { client, webhookUrl } = await this.clientPlataforma();
531	
532	    const valorCentavos = Math.round(fatura.valor * 100);
533	    const refId = `PLANO_${fatura.id}_${Date.now()}`;
534	
535	    let resposta: any;
536	    try {
537	      resposta = await client.criarOrdemPix({
538	        reference_id: refId,
539	        valor_centavos: valorCentavos,
540	        customer: {
541	          name: body.nome,
542	          email: body.email,
543	          tax_id: body.cpf_cnpj.replace(/\D/g, ''),
544	        },
545	        itens: [{ name: `Assinatura — fatura #${fatura.id}`, quantity: 1, unit_amount: valorCentavos }],
546	        webhook_url: webhookUrl,
547	      });
548	    } catch (e: any) {
549	      throw new BadRequestException(e?.message ?? 'Falha ao gerar cobrança no PagBank');
550	    }
551	
552	    const qrCode = resposta?.qr_codes?.[0];
553	    const pixCode = qrCode?.text ?? null;
554	    const pixQrUrl = qrCode?.links?.find((l: any) => l.media === 'image/png')?.href ?? null;
555	
556	    const { error } = await this.supabase.client
557	      .from('plano_faturas')
558	      .update({
559	        pagbank_order_id: resposta.id,
560	        reference_id: refId,
561	        pix_code: pixCode,
562	        pix_qr_url: pixQrUrl,
563	        atualizado_em: new Date().toISOString(),
564	      })
565	      .eq('id', fatura.id);
566	    if (error) throw error;
567	
568	    return { pix_code: pixCode, pix_qr_url: pixQrUrl, fatura_id: fatura.id };
569	  }
570	
571	  // Cartão confirma na hora (sem espera de webhook) — diferente do Pix
572	  private async pagarFaturaCartao(
573	    fatura: any,
574	    body: { nome: string; email: string; cpf_cnpj: string; card_encrypted?: string; parcelas?: number },
575	    metodo: 'credit_card' | 'debit_card',
576	  ) {
577	    if (!body.card_encrypted) throw new BadRequestException('Dados do cartão ausentes');
578	
579	    const { client, webhookUrl } = await this.clientPlataforma();
580	    const valorCentavos = Math.round(fatura.valor * 100);
581	    const refId = `PLANO_${fatura.id}_${Date.now()}`;
582	
583	    let resposta: any;
584	    try {
585	      resposta = await client.criarOrdemCartao({
586	        reference_id: refId,
587	        valor_centavos: valorCentavos,
588	        customer: {
589	          name: body.nome,
590	          email: body.email,
591	          tax_id: body.cpf_cnpj.replace(/\D/g, ''),
592	        },
593	        itens: [{ name: `Assinatura — fatura #${fatura.id}`, quantity: 1, unit_amount: valorCentavos }],
594	        card_encrypted: body.card_encrypted,
595	        parcelas: metodo === 'credit_card' ? (body.parcelas ?? 1) : 1,
596	        tipo: metodo === 'credit_card' ? 'CREDIT_CARD' : 'DEBIT_CARD',
597	        webhook_url: webhookUrl,
598	      });
599	    } catch (e: any) {
600	      throw new BadRequestException(e?.message ?? 'Falha ao processar cartão no PagBank');
601	    }
602	
603	    const charge = resposta?.charges?.[0];
604	    const pago = STATUS_PAGOS.includes(charge?.status);
605	
606	    const { error } = await this.supabase.client
607	      .from('plano_faturas')
608	      .update({
609	        pagbank_order_id: resposta.id,
610	        reference_id: refId,
611	        status: pago ? 'paga' : fatura.status,
612	        pago_em: pago ? new Date().toISOString() : null,
613	        atualizado_em: new Date().toISOString(),
614	      })
615	      .eq('id', fatura.id);
616	    if (error) throw error;
617	
618	    if (!pago) {
619	      throw new BadRequestException(charge?.status === 'DECLINED' ? 'Cartão recusado' : 'Pagamento não aprovado, tente novamente');
620	    }
621	
622	    return { pago: true, fatura_id: fatura.id };
623	  }
624	
625	  async processarWebhook(evento: any) {
626	    const payload = evento?.data ?? evento;
627	    const pagbankOrderId: string = payload?.id ?? payload?.reference_id;
628	    const charges: any[] = payload?.charges ?? [];
629	    const payments: any[] = payload?.payments ?? [];
630	
631	    const detalhe = charges[0] ?? payments[0];
632	    if (!detalhe) return { ignorado: true };
633	
634	    const statusPagbank: string = detalhe?.status ?? payload?.status ?? '';
635	    if (!STATUS_PAGOS.includes(statusPagbank)) return { ignorado: true };
636	
637	    const { data: fatura } = await this.supabase.client
638	      .from('plano_faturas')
639	      .select('id, status')
640	      .eq('pagbank_order_id', pagbankOrderId)
641	      .maybeSingle();
642	
643	    if (!fatura) return { ignorado: true, motivo: 'fatura não encontrada' };
644	    if (fatura.status === 'paga') return { ignorado: true, motivo: 'já processado' };
645	
646	    await this.supabase.client
647	      .from('plano_faturas')
648	      .update({ status: 'paga', pago_em: new Date().toISOString(), atualizado_em: new Date().toISOString() })
649	      .eq('id', fatura.id);
650	
651	    return { processado: true, fatura_id: fatura.id };
652	  }
653	}
