324	      ? new Date(assinatura.ultimo_periodo_faturado_fim)
325	      : null;
326	
327	    // Se já existe fatura pendente/vencida de QUALQUER período, "Renovar agora"
328	    // não pode gerar outra — o dono tem que pagar a que já existe primeiro.
329	    let temPendenteAberta = false;
330	    if (forcar) {
331	      const { data: pendenteExistente, error: pendErroCheck } = await this.supabase.client
332	        .from('plano_faturas')
333	        .select('id')
334	        .eq('assinatura_id', assinatura.id)
335	        .in('status', ['pendente', 'vencida'])
336	        .limit(1)
337	        .maybeSingle();
338	      if (pendErroCheck) throw pendErroCheck;
339	      temPendenteAberta = !!pendenteExistente;
340	    }
341	
342	    // eslint-disable-next-line no-constant-condition
343	    while (true) {
344	      const fimPeriodo = somarMeses(inicioPeriodo, meses);
345	      const periodoFechado = fimPeriodo < agora;
346	      if (!periodoFechado && !forcar) break;
