351	        // Período em aberto forçado: se já existe fatura pra esse período (de um
352	        // "Renovar agora" anterior), não gera outra nem avança o ciclo de novo —
353	        // senão cada clique empurraria a cobrança um mês pra frente.
354	        const { data: jaExiste, error: existeErro } = await this.supabase.client
