404	      inicioPeriodo = fimPeriodo;
405	
406	      if (!periodoFechado) break; // gerou o período em aberto sob demanda — não continua pro futuro
407	    }
408	
409	    if (ultimoFimFaturado && ultimoFimFaturado.getTime() !== new Date(assinatura.ultimo_periodo_faturado_fim ?? 0).getTime()) {
410	      await this.supabase.client
411	        .from('assinaturas')
